<?php
declare(strict_types=1);require __DIR__.'/../config/auth.php';require __DIR__.'/../config/database.php';require __DIR__.'/../config/listing_integrity.php';require_admin();if(empty($_SESSION['admin_csrf']))$_SESSION['admin_csrf']=bin2hex(random_bytes(32));$msg='';$err='';if($_SERVER['REQUEST_METHOD']==='POST'){if(!hash_equals($_SESSION['admin_csrf'],(string)($_POST['csrf']??'')))$err='Güvenlik doğrulaması geçersiz.';else try{$action=$_POST['action']??'';if($action==='create'){$company=trim((string)$_POST['company_name']);$name=trim((string)$_POST['full_name']);$email=filter_var($_POST['email']??'',FILTER_VALIDATE_EMAIL);$pass=(string)($_POST['password']??'');if($company===''||$name===''||!$email||strlen($pass)<10)throw new RuntimeException('Ünvan, yetkili, geçerli e-posta ve en az 10 karakter şifre zorunludur.');$pdo=db();$pdo->beginTransaction();$q=$pdo->prepare("INSERT INTO agencies(company_name,license_number,country_code,status) VALUES(?,?,?,'active') RETURNING id");$q->execute([$company,trim((string)$_POST['license_number'])?:null,strtoupper(trim((string)$_POST['country_code']??'TR'))]);$id=(int)$q->fetchColumn();$pdo->prepare("INSERT INTO agency_users(agency_id,full_name,email,password_hash,role) VALUES(?,?,?,?, 'owner')")->execute([$id,$name,$email,password_hash($pass,PASSWORD_DEFAULT)]);$pdo->commit();record_audit_event('admin',null,'agency.created','agency',$id);$msg='Acente hesabı aktif oluşturuldu.';}if($action==='status'){db()->prepare('UPDATE agencies SET status=? WHERE id=?')->execute([$_POST['status']==='active'?'active':'suspended',(int)$_POST['id']]);$msg='Acente durumu güncellendi.';}}catch(Throwable $e){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();$err=$e->getMessage();}}$rows=db()->query('SELECT a.*,u.full_name,u.email FROM agencies a LEFT JOIN agency_users u ON u.agency_id=a.id AND u.role=\'owner\' ORDER BY a.id DESC')->fetchAll();?><!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Acenteler | NEXUS Admin</title><style>body{font-family:Arial;background:#f7f7f2;margin:0}.w{width:min(1000px,calc(100% - 32px));margin:35px auto}.c{background:#fff;border:1px solid #ddd;padding:18px;margin:15px 0}.f{display:grid;gap:8px}.r{display:grid;grid-template-columns:repeat(2,1fr);gap:8px}input,button,select{padding:9px}.ok{background:#e6f8c7;padding:9px}.er{background:#ffe2de;padding:9px}</style></head><body><main class="w"><a href="/nexustraveltech/admin/">← Panel</a><h1>Acente yönetimi</h1><?php if($msg):?><p class="ok"><?=htmlspecialchars($msg)?></p><?php endif;?><?php if($err):?><p class="er"><?=htmlspecialchars($err)?></p><?php endif;?><form method="post" class="c f"><input type="hidden" name="csrf" value="<?=htmlspecialchars($_SESSION['admin_csrf'])?>"><input type="hidden" name="action" value="create"><div class="r"><input name="company_name" placeholder="Acente ünvanı" required><input name="license_number" placeholder="TÜRSAB / lisans no"></div><div class="r"><input name="full_name" placeholder="Yetkili ad soyad" required><input name="email" type="email" placeholder="E-posta" required></div><div class="r"><input name="password" type="password" placeholder="İlk şifre (en az 10 karakter)" required><input name="country_code" value="TR" maxlength="2"></div><button>Aktif acente oluştur</button></form><?php foreach($rows as $r):?><section class="c"><b><?=htmlspecialchars($r['company_name'])?></b> · <?=htmlspecialchars($r['status'])?><p><?=htmlspecialchars($r['full_name']?:'')?> · <?=htmlspecialchars($r['email']?:'')?> · <?=htmlspecialchars($r['license_number']?:'')?></p><form method="post"><input type="hidden" name="csrf" value="<?=htmlspecialchars($_SESSION['admin_csrf'])?>"><input type="hidden" name="action" value="status"><input type="hidden" name="id" value="<?=$r['id']?>"><select name="status"><option value="active" <?=$r['status']==='active'?'selected':''?>>Aktif</option><option value="suspended" <?=$r['status']==='suspended'?'selected':''?>>Askıya al</option></select><button>Kaydet</button></form></section><?php endforeach;?></main></body></html>
